        test_file = TESTS_DIR / "test_parallel_probe.py"
        test_file.write_text(
            "def test_parallel():\n"
            "    assert True\n"
        )

        def run_pytest(_):
            return subprocess.run(
                [sys.executable, "-m", "pytest", "-q", str(test_file)],
                capture_output=True,
                text=True,
                timeout=30,
            )

        try:
            with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
                futures = [executor.submit(run_pytest, i) for i in range(4)]
                results = [f.result() for f in futures]

            for r in results:
                assert r.returncode == 0, f"Parallel run failed: {r.stderr}"
        finally:
            test_file.unlink(missing_ok=True)

