class TestConftestFixtureContracts:
    """Validate any fixtures defined in conftest.py are well-formed."""

    def test_fixture_names_are_snake_case(self):
        """Static check: fixture names must follow PEP8."""
        if not CONFTEST_PATH.exists():
            pytest.skip("conftest.py not present")

        content = CONFTEST_PATH.read_text()
        import re
        fixture_decorators = re.findall(r"@pytest\.fixture(?:\([^)]*\))?\s*\ndef\s+(\w+)", content)
        for name in fixture_decorators:
            assert name.islower(), f"Fixture '{name}' not snake_case"

    def test_no_duplicate_fixture_definitions(self):
        """Static check: no duplicate fixture names."""
        if not CONFTEST_PATH.exists():
            pytest.skip("conftest.py not present")

        content = CONFTEST_PATH.read_text()
        import re
        fixture_names = re.findall(r"def\s+(test_\w+|fixture_\w+)", content)
        duplicates = {name for name in fixture_names if fixture_names.count(name) > 1}
        assert not duplicates, f"Duplicate definitions: {duplicates}"


